/// The gallery's example of `ShortcutSheet`, with its settings taken from the story.
#[allow(unused_variables, unused_mut, clippy::redundant_clone, clippy::let_and_return, clippy::clone_on_copy)]
fn render(args: &Args) -> AnyView {
    Box::new({
        let arg_title = args.text("title");

        let open = State::new(args.bool("open"));
        let show = open.clone();
        VStack::new((
            Button::new("Show shortcuts")
                .style(ButtonStyle::Secondary)
                .icon(IconName::Keyboard)
                .on_click(move || show.set(true)),
            {
                let mut it = ShortcutSheet::new(open.binding())
                    .group("Navigate", [("←", "Previous photo"), ("→", "Next photo")])
                    .group("Rate", [("1–5", "Give a score"), ("0", "Take it away")]);
                if !arg_title.is_empty() {
                    it = it.title(arg_title.clone());
                }
                it
            },
        ))
    })
}

impl ComponentBook for ShortcutSheet {
    fn book() -> Meta {
        Meta::new("Display and feedback/ShortcutSheet", render)
            .summary("Dialog listing the keys of a screen, in groups.")
            .arg(ArgType::text("title", "").description("Empty leaves it as the component has it."))
            .arg(ArgType::bool("open", false).description("How the example starts."))
            .story("Example", Args::new())
            .story("Open", Args::new().with("open", true))
    }
}
